+/*
+ * Decode packets between electric vehicles (EV) and charging stations (EVSE), also known as V2G messages.
+ * ISO 15118
+ *
+ * https://github.com/dspace-group/dsV2Gshark
+ */
+
+#include "config.h"
+//#define WS_LOG_DOMAIN "v2gtp"
+
+#include <wireshark.h>
+
+#include <epan/packet.h>
+#include <epan/prefs.h>
+
+#include "packet-tcp.h"
+#include "packet-tls.h"
+
+dissector_handle_t v2g_msg_handle;
+
+/* Prototypes */
+void proto_reg_handoff_v2gtp(void);
+void proto_register_v2gtp(void);
+
+static int proto_v2gtp;
+static int hf_v2gtp_version;
+static int hf_v2gtp_inverse_version;
+static int hf_v2gtp_payload_type;
+static int hf_v2gtp_payload_length;
+static int hf_v2gtp_payload;
+static int hf_v2gtp_security;
+static int hf_v2gtp_transport_prot;
+static int hf_v2gtp_secc_ip_addr;
+static int hf_v2gtp_secc_port;
+static int hf_v2gtp_exi;
+static int hf_v2gtp_exi_cookie;
+static int hf_v2gtp_exi_dis_bits;
+static int hf_v2gtp_exi_pb_opt;
+static int hf_v2gtp_exi_vers;
+
+static int ett_v2gtp;
+static int ett_v2g_secc_disc_prot_req;
+static int ett_v2g_msg;
+static int ett_v2g_exi;
+
+static dissector_handle_t v2gtp_handle;
+static dissector_handle_t v2gtp_tcp_handle;
+
+#define V2G_SAP_PAYLOAD 0x8001                //32769
+#define V2G_PART20MAINSTREAMPAYLOAD  0x8002
+#define V2G_PART20ACMAINSTREAMPAYLOAD 0x8003
+#define V2G_PART20DCMAINSTREAMPAYLOAD 0x8004
+#define V2G_SDP_REQ_MSG 0x9000
+#define V2G_SDP_RSP_MSG 0x9001
+static const value_string v2gtp_payload_type_id_values[] = {
+    { V2G_SAP_PAYLOAD, "SAPPayload" },
+    { V2G_PART20MAINSTREAMPAYLOAD, "Part20MainstreamPayload" },
+    { V2G_PART20ACMAINSTREAMPAYLOAD, "Part20ACMainstreamPayload" },
+    { V2G_PART20DCMAINSTREAMPAYLOAD, "Part20DCMainstreamPayload" },
+    { 0x8005, "Part20ACDPMainstreamPayload" },
+    { 0x8006, "Part20WPTMainstreamPayload" },
+    /* 0x8007 - 0x8100 Not applicable Reserved for future use */
+    { 0x8101, "ScheduleRenegotiationPayload" },
+    { 0x8102, "MeteringConfirmationPayload" },
+    { 0x8103, "ACDPSystemStatusPayload" },
+    { 0x8104, "ParkingStatusPayload" },
+    /* 0x8105 - 0x8FFF Not applicable Reserved for future use*/
+    { V2G_SDP_REQ_MSG, "SDP request message " },
+    { V2G_SDP_RSP_MSG, "SDP response message" },
+    { 0x9002, "SDP request message Wireless" },
+    { 0x9003, "SDP response message Wireless" },
+    { 0x9004, "SDP EMSP request message" },
+    { 0x9005, "SDP EMSP response message" },
+    /* 0x9004 - 0x9FFF Not applicable Reserved for future use*/
+    /* 0xA000 - 0xFFFF Not applicable Available for manufacturer specific use.
+     *                 Uniqueness of those identifiers is not guaranteed by this document.
+     */
+    { 0, NULL }
+};
+static const value_string v2gtp_security_values[] = {
+        { 0x00, "Secured with TLS" },
+        { 0x10, "No transport layer security" },
+        { 0, NULL }
+};
+
+static const value_string v2gtp_transp_prot_values[] = {
+        { 0x00, "TCP" },
+        { 0, NULL }
+};
+
+static unsigned tls_port_pref = 0;
+
+static int
+dissect_v2gtp_exi(tvbuff_t* tvb, packet_info* pinfo _U_, proto_item* exi_item)
+{
+    unsigned offset = 0;
+
+    proto_tree* tree = proto_item_add_subtree(exi_item, ett_v2g_exi);
+    /*
+     * EXI Header
+     */
+    /* EXI Cookie (Optional)*/
+    if (tvb_strneql(tvb, 0, "$EXI", strlen("$EXI")) == 0) {
+        proto_tree_add_item(tree, hf_v2gtp_exi_cookie, tvb, offset, 4, ENC_ASCII);
+        offset += 4;
+    }
+    /* Distinguishing Bits */
+    proto_tree_add_item(tree, hf_v2gtp_exi_dis_bits, tvb, offset, 1, ENC_BIG_ENDIAN);
+    /* Presence Bit for EXI Options */
+    proto_tree_add_item(tree, hf_v2gtp_exi_pb_opt, tvb, offset, 1, ENC_BIG_ENDIAN);
+    /* EXI Format Version */
+    proto_tree_add_item(tree, hf_v2gtp_exi_vers, tvb, offset, 1, ENC_BIG_ENDIAN);
+
+    return offset;
+}
+
+
+/*
+ * V2GTP Header Structure (8 Bytes)The header uses Big-endian format:
+    Size    Field       Description
+    1 Byte  Protocol    Currently 0x01 (ISO 15118-2) or 0x02 (ISO 15118-20)
+            Version
+    1 Byte  Inverse     The bitwise NOT of the protocol version (e.g., if version is 0x01, this is 0xFE).
+            Version
+    2 Bytes Payload     Type of message (e.g., 0x8001 for EXI, 0x9000 for SDP Request).
+            Type
+    4 Bytes Payload     Length of the following V2G message (payload) in bytes (unsigned 32-bit integer).
+            Length
+*/
+
+#define V2GTP_MIN_LENGTH 8
+
+static int
+dissect_v2gtp(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, void *data _U_)
+{
+    /* Set up structures needed to add the protocol subtree and manage it */
+    proto_item* ti, *exi_item;/**expert_ti;*/
+    proto_tree * v2gtp_tree;
+    proto_tree* subtree;
+
+    unsigned offset = 0;
+    uint32_t len, payload_type;
+    tvbuff_t* exi_tvb;
+    /*** HEURISTICS ***/
+
+    /* Check that the packet is long enough for it to belong to us. */
+    if (tvb_reported_length(tvb) < V2GTP_MIN_LENGTH)
+        return 0;
+
+    col_set_str(pinfo->cinfo, COL_PROTOCOL, "V2GTP");
+    col_clear(pinfo->cinfo, COL_INFO);
+
+    ti = proto_tree_add_item(tree, proto_v2gtp, tvb, 0, -1, ENC_NA);
+    v2gtp_tree = proto_item_add_subtree(ti, ett_v2gtp);
+
+    proto_tree_add_item(v2gtp_tree, hf_v2gtp_version, tvb, offset, 1, ENC_BIG_ENDIAN);
+    offset ++;
+    proto_tree_add_item(v2gtp_tree, hf_v2gtp_inverse_version, tvb, offset, 1, ENC_BIG_ENDIAN);
+    offset++;
+    proto_tree_add_item_ret_uint(v2gtp_tree, hf_v2gtp_payload_type, tvb, offset, 2, ENC_BIG_ENDIAN, &payload_type);
+    col_set_str(pinfo->cinfo, COL_INFO, val_to_str_const(payload_type, v2gtp_payload_type_id_values, "Unknown"));
+
+    offset += 2;
+    proto_tree_add_item_ret_uint(v2gtp_tree, hf_v2gtp_payload_length, tvb, offset, 4, ENC_BIG_ENDIAN, &len);
+    offset += 4;
+
+    exi_tvb = tvb_new_subset_length(tvb, offset, len);
+
+    switch (payload_type) {
+    case V2G_SAP_PAYLOAD: /* 0x8001 */
+    case V2G_PART20MAINSTREAMPAYLOAD: /* 0x8002 32770 */
+    case V2G_PART20ACMAINSTREAMPAYLOAD: /* 0x8003 32771*/
+    case V2G_PART20DCMAINSTREAMPAYLOAD: /* 0x8004 32772*/
+        subtree = proto_tree_add_subtree(v2gtp_tree, tvb, offset, len, ett_v2g_msg, NULL, "V2G Message");
+        exi_item = proto_tree_add_item(subtree, hf_v2gtp_exi, tvb, offset, len, ENC_NA);
+        exi_tvb = tvb_new_subset_length(tvb, offset, len);
+        if (v2g_msg_handle) {
+            call_dissector(v2g_msg_handle, exi_tvb, pinfo, tree);
+        } else {
+            dissect_v2gtp_exi(exi_tvb, pinfo, exi_item);
+        }
+        break;
+    case V2G_SDP_REQ_MSG:
+        subtree = proto_tree_add_subtree(v2gtp_tree, tvb, offset, len, ett_v2g_secc_disc_prot_req, NULL, "V2G SECC Discovery Protocol Request");
+        proto_tree_add_item(subtree, hf_v2gtp_security, tvb, offset, 1, ENC_BIG_ENDIAN);
+        offset++;
+        proto_tree_add_item(subtree, hf_v2gtp_transport_prot, tvb, offset, 1, ENC_BIG_ENDIAN);
+        offset++;
+        break;
+    case V2G_SDP_RSP_MSG:
+    {
+        conversation_t* conversation;
+        address dst_addr, null_addr;
+        ws_in6_addr secc_ip_addr;
+        uint32_t secc_port;
+
+        subtree = proto_tree_add_subtree(v2gtp_tree, tvb, offset, len, ett_v2g_secc_disc_prot_req, NULL, "V2G SECC Discovery Protocol Response");
+        proto_tree_add_item_ret_ipv6(subtree, hf_v2gtp_secc_ip_addr, tvb, offset, 16, ENC_BIG_ENDIAN, &secc_ip_addr);
+        offset += 16;
+        proto_tree_add_item_ret_uint(subtree, hf_v2gtp_secc_port, tvb, offset, 2, ENC_BIG_ENDIAN, &secc_port);
+        offset += 2;
+        proto_tree_add_item(subtree, hf_v2gtp_security, tvb, offset, 1, ENC_BIG_ENDIAN);
+        offset++;
+        proto_tree_add_item(subtree, hf_v2gtp_transport_prot, tvb, offset, 1, ENC_BIG_ENDIAN);
+        offset++;
+        if ((!pinfo->fd->visited)&&(secc_port)){
+            clear_address(&null_addr);
+
+            set_address(&dst_addr, AT_IPv6, 16, &secc_ip_addr);
+
+            conversation = find_conversation(pinfo->num, &dst_addr,
+                &null_addr, CONVERSATION_TCP, secc_port,
+                0, NO_ADDR_B | NO_PORT_B);
+
+            if (conversation == NULL) {
+                /* It's not part of any conversation - create a new one. */
+                conversation = conversation_new(pinfo->num, &dst_addr,
+                    &null_addr, CONVERSATION_TCP, secc_port,
+                    0, NO_ADDR2 | NO_PORT2);
+
+                /* Set dissector */
+                conversation_set_dissector(conversation, v2gtp_tcp_handle);
+            }
+        }
+        break;
+    }
+    default:
+        proto_tree_add_item(v2gtp_tree, hf_v2gtp_payload, tvb, offset, len, ENC_NA);
+        break;
+    }
+
+    return tvb_captured_length(tvb);
+}
+
+static unsigned
+get_v2gtp_pdu_len(packet_info* pinfo _U_, tvbuff_t* tvb, int offset, void* data _U_)
+{
+
+    /* PDU length = Message length */
+    return (tvb_get_ntohl(tvb, offset + 4) + 8);
+}
+
+static int
+dissect_v2gtp_tcp(tvbuff_t* tvb, packet_info* pinfo, proto_tree* tree, void* data )
+{
+
+    if (tvb_reported_length(tvb) < V2GTP_MIN_LENGTH) {
+        return 0;
+    }
+    if (tvb_get_ntohs(tvb, 0) != 0x01fe) {
+        return 0;
+    }
+
+    tcp_dissect_pdus(tvb, pinfo, tree, true, V2GTP_MIN_LENGTH,
+        get_v2gtp_pdu_len, dissect_v2gtp, data);
+
+    return tvb_captured_length(tvb);
+
+}
+
+/* Register the protocol with Wireshark.
+ *
+ * This format is required because a script is used to build the C function that
+ * calls all the protocol registration.
+ */
+void
+proto_register_v2gtp(void)
+{
+    module_t        *v2gtp_module;
+
+    static hf_register_info hf[] = {
+        { &hf_v2gtp_version,
+          { "Protocol version", "v2gtp.version",
+            FT_UINT8, BASE_DEC, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_inverse_version,
+          { "Inverse protocol version", "v2gtp.inverse_version",
+            FT_UINT8, BASE_HEX, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_payload_type,
+          { "Payload type", "v2gtp.payload_type",
+            FT_UINT16, BASE_HEX, VALS(v2gtp_payload_type_id_values), 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_payload_length,
+          { "Payload length", "v2gtp.payload_length",
+            FT_UINT32, BASE_DEC, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_payload,
+          { "Payload", "v2gtp.payload",
+            FT_BYTES, BASE_NO_DISPLAY_VALUE, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_security,
+          { "Security", "v2gtp.security",
+            FT_UINT8, BASE_DEC, VALS(v2gtp_security_values), 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_transport_prot,
+          { "Transport Protocol", "v2gtp.transport_prot",
+            FT_UINT8, BASE_DEC, VALS(v2gtp_transp_prot_values), 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_secc_ip_addr,
+        { "SECC IP Address", "v2gtp.cmn.secc_ip_addr",
+            FT_IPv6, BASE_NONE, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_secc_port,
+          { "SECC Port", "v2gtp.secc_port",
+            FT_UINT16, BASE_DEC, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_exi,
+          { "EXI", "v2gtp.exi",
+            FT_BYTES, BASE_NONE, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_exi_cookie,
+          { "EXI Cookie", "v2gtp.exi_hf_v2gtp.exi.cookie",
+            FT_STRING, BASE_NONE, NULL, 0x0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_exi_dis_bits,
+          { "Distinguishing Bits", "v2gtp.exi.dis_bits",
+            FT_UINT8, BASE_HEX, NULL, 0xc0,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_exi_pb_opt,
+          { "Presence Bit for EXI Options", "v2gtp.exi.pb_opt",
+            FT_UINT8, BASE_HEX, NULL, 0x20,
+            NULL, HFILL }
+        },
+        { &hf_v2gtp_exi_vers,
+          { "EXI Format Version", "v2gtp.exi.vers",
+            FT_UINT8, BASE_HEX, NULL, 0x1f,
+            NULL, HFILL }
+        },
+    };
+
+    static int *ett[] = {
+        &ett_v2gtp,
+        &ett_v2g_secc_disc_prot_req,
+        &ett_v2g_msg,
+        &ett_v2g_exi
+    };
+
+    proto_v2gtp = proto_register_protocol("V2G Transfer Protocol", "V2GTP", "v2gtp");
+
+    proto_register_field_array(proto_v2gtp, hf, array_length(hf));
+    proto_register_subtree_array(ett, array_length(ett));
+
+    v2gtp_handle = register_dissector("v2gtp", dissect_v2gtp, proto_v2gtp);
+    v2gtp_tcp_handle = register_dissector("v2gtp.tcp", dissect_v2gtp_tcp, proto_v2gtp);
+
+    v2gtp_module = prefs_register_protocol(proto_v2gtp, proto_reg_handoff_v2gtp);
+
+    prefs_register_uint_preference(v2gtp_module, "tls.port", "v2gtp TLS Port",
+            " v2gtp TLS port if other than the default",
+            10, &tls_port_pref);
+
+}
+
+void
+proto_reg_handoff_v2gtp(void)
+{
+    static bool initialized = false;
+    static int current_tls_port_pref;
+
+    if (!initialized) {
+        dissector_add_uint_range_with_preference("tcp.port", "", v2gtp_tcp_handle);
+
+        dissector_add_uint_range_with_preference("udp.port", "", v2gtp_handle);
+
+        initialized = true;
+    } else {
+        ssl_dissector_delete(current_tls_port_pref, v2gtp_tcp_handle);
+    }
+
+    ssl_dissector_add(tls_port_pref, v2gtp_tcp_handle);
+    current_tls_port_pref = tls_port_pref;
+    v2g_msg_handle = find_dissector("v2gmsg");
+}
